mapper.insert:
INSERT INTO app_conversation_branch (
    conversation_id, user_id, parent_branch_id, fork_message_id, opening_variant_index, title, is_default
) VALUES (
    #{conversationId}, #{userId}, #{parentBranchId}, #{forkMessageId}, #{openingVariantIndex}, #{title}, #{defaultBranch}
)

mapper.select:
SELECT *
FROM app_conversation_branch
WHERE conversation_id = #{conversationId}
  AND id = #{branchId}
  AND deleted_at IS NULL
LIMIT 1

SELECT *
FROM app_conversation_branch
WHERE conversation_id = #{conversationId}
  AND opening_variant_index = #{openingVariantIndex}
  AND deleted_at IS NULL
LIMIT 1

mapper.update:
UPDATE app_conversation_branch
SET updated_at = CURRENT_TIMESTAMP
WHERE id = #{branchId}

UPDATE app_conversation_branch
SET memory_source_revision = memory_source_revision + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND id = #{branchId}
  AND deleted_at IS NULL
